function validate([root, start]) {
  const values = root.filter(v => v !== null);
  if (values.length < 1 || root[0] === null) return 'The tree needs at least 1 node.';
  if (values.length > 100000) return 'The tree has at most 10^5 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Every node value is an integer between 1 and 10^5.';
  if (new Set(values).size !== values.length) return 'Node values must be distinct.';
  if (!values.includes(start)) return 'start must be the value of a node in the tree.';
  return null;
}

