function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 900 + Math.floor(rand() * 100) : 1 + Math.floor(rand() * 12);
  // Distinct values: a small range for small trees, the full range for large ones.
  const pool = large ? 100000 : 30;
  const used = new Set();
  const value = () => {
    for (;;) {
      const v = 1 + Math.floor(rand() * pool);
      if (!used.has(v)) { used.add(v); return v; }
    }
  };
  // Some trees start with a long downward chain, which makes deep paths.
  const chain = large ? (rand() < 0.4 ? 100 + Math.floor(rand() * 300) : 1) : (rand() < 0.25 ? n : 1);
  const nodes = [{ val: value(), left: null, right: null }];
  for (let i = 1; i < chain; i++) {
    nodes[i - 1][rand() < 0.5 ? 'left' : 'right'] = i;
    nodes.push({ val: value(), left: null, right: null });
  }
  const slots = [[chain - 1, 'left'], [chain - 1, 'right']];
  for (let i = chain; i < n; i++) {
    const k = Math.floor(rand() * slots.length);
    const [parent, side] = slots[k];
    slots[k] = slots[slots.length - 1];
    slots.pop();
    nodes[parent][side] = i;
    nodes.push({ val: value(), left: null, right: null });
    slots.push([i, 'left'], [i, 'right']);
  }
  // The infection starts at the root, at the last node created (often deep) or anywhere.
  const pick = rand();
  const start = pick < 0.2 ? nodes[0].val : pick < 0.4 ? nodes[n - 1].val : nodes[Math.floor(rand() * n)].val;
  // Level-order serialisation with null for missing children, trailing nulls removed.
  const out = [];
  const queue = [0];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) { out.push(null); continue; }
    const node = nodes[queue[q]];
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return [out, start];
}
